"""Regenerate pins.bzl from NVIDIA's CUDA apt repository index.

Usage: python3 bazel/third_party/tensorrt/update_pins.py 10.16.1.11-1+cuda13.2

Pins the TensorRT runtime and header packages (the ones ansible/roles/tensorrt installs, minus the static-library
-dev packages) for Ubuntu 24.04 x86_64 and sbsa (Jetson Thor), each by the sha256 from the repository index.
"""

import gzip
import re
import sys
import urllib.request

REPO = "https://developer.download.nvidia.com/compute/cuda/repos/ubuntu2404"
ARCHES = {"x86_64": "x86_64", "sbsa": "aarch64"}  # apt repo dir -> pins key (Bazel cpu)
PACKAGES = [
    "libnvinfer10",
    "libnvinfer-plugin10",
    "libnvonnxparsers10",
    "libnvinfer-headers-dev",
    "libnvinfer-headers-plugin-dev",
    "libnvonnxparsers-dev",
]


def main(version):
    out = ['"""Generated by update_pins.py; do not edit by hand."""', "", f'TENSORRT_VERSION = "{version}"', "",
           "TENSORRT_DEBS = {"]
    for repo_arch, cpu in ARCHES.items():
        index = gzip.decompress(urllib.request.urlopen(f"{REPO}/{repo_arch}/Packages.gz").read()).decode()
        found = {}
        for block in index.split("\n\n"):
            fields = dict(re.findall(r"^(Package|Version|Filename|SHA256): (.*)$", block, re.M))
            if fields.get("Package") in PACKAGES and fields.get("Version") == version:
                found[fields["Package"]] = (f"{REPO}/{repo_arch}/{fields['Filename'].removeprefix('./')}", fields["SHA256"])
        missing = set(PACKAGES) - set(found)
        if missing:
            sys.exit(f"{repo_arch}: {version} not found for {sorted(missing)}")
        out.append(f'    "{cpu}": [')
        out += [f'        ("{found[p][0]}", "{found[p][1]}"),' for p in PACKAGES]
        out.append("    ],")
    out += ["}", ""]
    open(__file__.rsplit("/", 1)[0] + "/pins.bzl", "w").write("\n".join(out))


if __name__ == "__main__":
    main(sys.argv[1])
